package main

import (
 "database/sql"
 "net/http"
 "strings"
 "time"
)

func sandboxClearing(tx *sql.Tx,r *http.Request,org,currency string)(string,error){var id string;err:=tx.QueryRowContext(r.Context(),`SELECT id FROM accounts WHERE organization_id=$1 AND currency=$2 AND account_type='sandbox_clearing' ORDER BY created_at LIMIT 1`,org,currency).Scan(&id);if err==nil{return id,nil};if err!=sql.ErrNoRows{return "",err};id="acc_sandbox_"+newID();_,err=tx.ExecContext(r.Context(),`INSERT INTO accounts(id,organization_id,currency,account_type) VALUES($1,$2,$3,'sandbox_clearing')`,id,org,currency);return id,err}

func (a *App) confirmCollection(w http.ResponseWriter,r *http.Request,id string){var in struct{AccountID string `json:"account_id"`};if decode(r,&in)!=nil||in.AccountID==""{bad(w,r,"account_id is required");return};key,hash,err:=requireIdempotencyKey(r);if err!=nil{bad(w,r,err.Error());return};org:=currentOrgID(r,a.orgID);tx,err:=a.db.BeginTx(r.Context(),&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer tx.Rollback();status,body,replay,err:=reserveIdempotency(r.Context(),tx,org,key,hash);if err!=nil{idempotencyFailure(w,r,err);return};if replay{writeRawJSON(w,status,body);return}
 if err=ensurePeriodOpen(r.Context(),tx,org,time.Now());err!=nil{periodGuardFailure(w,r,err);return}
 var amount int64;var currency,state string;err=tx.QueryRowContext(r.Context(),`SELECT amount_minor,currency,status FROM collections WHERE id=$1 AND organization_id=$2 FOR UPDATE`,id,org).Scan(&amount,&currency,&state);if err==sql.ErrNoRows{notFound(w,r);return};if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};if state!="pending"{writeJSON(w,409,problem{Error:"collection is not pending"});return};if held,holdErr:=openRiskCase(r.Context(),tx,org,"collection",id);holdErr!=nil{writeJSON(w,500,problem{Error:"risk case check failed"});return}else if held{writeJSON(w,409,problem{Error:"collection is held for risk review; resolve its case before confirming",RequestID:requestID(r)});return};var accountCurrency string;err=tx.QueryRowContext(r.Context(),`SELECT currency FROM accounts WHERE id=$1 AND organization_id=$2 AND status='active' FOR UPDATE`,in.AccountID,org).Scan(&accountCurrency);if err!=nil||strings.TrimSpace(accountCurrency)!=strings.TrimSpace(currency){writeJSON(w,400,problem{Error:"account is unavailable or currency does not match"});return};clearing,err:=sandboxClearing(tx,r,org,currency);if err!=nil{writeJSON(w,500,problem{Error:"sandbox clearing account setup failed"});return}
 entry:="jrn_"+newID();_,err=tx.ExecContext(r.Context(),`INSERT INTO journal_entries(id,organization_id,reference_type,reference_id,currency,amount_minor) VALUES($1,$2,'collection',$3,$4,$5)`,entry,org,id,currency,amount);if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO journal_lines(journal_entry_id,organization_id,account_id,side,amount_minor,currency) VALUES($1,$2,$3,'debit',$5,$6),($1,$2,$4,'credit',$5,$6)`,entry,org,clearing,in.AccountID,amount,currency)};if err==nil{_,err=tx.ExecContext(r.Context(),`UPDATE collections SET status='succeeded',credited_account_id=$3 WHERE id=$1 AND organization_id=$2`,id,org,in.AccountID)};if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO outbox_events(id,organization_id,aggregate_type,aggregate_id,event_type,payload) VALUES($1,$2,'collection',$3,'collection.succeeded',jsonb_build_object('collection_id',$3::text,'status','succeeded','amount',$4::bigint,'currency',$5::text))`,"evt_"+newID(),org,id,amount,currency)};if err!=nil{writeJSON(w,500,problem{Error:"sandbox collection posting failed"});return};result:=map[string]any{"id":id,"status":"succeeded","amount":amount,"currency":strings.TrimSpace(currency),"mode":"sandbox","notice":"simulated payment confirmation; no external payment occurred"};if err=storeIdempotency(r.Context(),tx,org,key,200,result);err!=nil{idempotencyFailure(w,r,err);return};if err=tx.Commit();err!=nil{writeJSON(w,409,problem{Error:"collection confirmation conflict"});return};writeJSON(w,200,result)
}

func (a *App) refundCollection(w http.ResponseWriter,r *http.Request,id string){var in struct{Amount int64 `json:"amount"`;Reference string `json:"reference"`};if decode(r,&in)!=nil||in.Amount<=0||in.Reference==""{bad(w,r,"positive amount and reference are required");return};key,hash,err:=requireIdempotencyKey(r);if err!=nil{bad(w,r,err.Error());return};org:=currentOrgID(r,a.orgID);tx,err:=a.db.BeginTx(r.Context(),&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer tx.Rollback();status,body,replay,err:=reserveIdempotency(r.Context(),tx,org,key,hash);if err!=nil{idempotencyFailure(w,r,err);return};if replay{writeRawJSON(w,status,body);return}
 if err=ensurePeriodOpen(r.Context(),tx,org,time.Now());err!=nil{periodGuardFailure(w,r,err);return}
 var collectionAmount int64;var currency,state string;var accountID sql.NullString;err=tx.QueryRowContext(r.Context(),`SELECT amount_minor,currency,status,credited_account_id FROM collections WHERE id=$1 AND organization_id=$2 FOR UPDATE`,id,org).Scan(&collectionAmount,&currency,&state,&accountID);if err==sql.ErrNoRows{notFound(w,r);return};if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};if state!="succeeded"||!accountID.Valid{writeJSON(w,409,problem{Error:"only succeeded collections can be refunded"});return};var refunded int64;err=tx.QueryRowContext(r.Context(),`SELECT COALESCE(SUM(amount_minor),0) FROM refunds WHERE organization_id=$1 AND collection_id=$2 AND status='completed'`,org,id).Scan(&refunded);if err!=nil||in.Amount>collectionAmount-refunded{writeJSON(w,409,problem{Error:"refund exceeds the unrefunded collection amount"});return};clearing,err:=sandboxClearing(tx,r,org,currency);if err!=nil{writeJSON(w,500,problem{Error:"sandbox clearing account setup failed"});return};p:=principalFrom(r);refundID:="ref_"+newID();_,err=tx.ExecContext(r.Context(),`INSERT INTO refunds(id,organization_id,collection_id,amount_minor,currency,reference,created_by) VALUES($1,$2,$3,$4,$5,$6,$7)`,refundID,org,id,in.Amount,currency,in.Reference,nullable(p.userID));entry:="jrn_"+newID();if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO journal_entries(id,organization_id,reference_type,reference_id,currency,amount_minor) VALUES($1,$2,'refund',$3,$4,$5)`,entry,org,refundID,currency,in.Amount)};if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO journal_lines(journal_entry_id,organization_id,account_id,side,amount_minor,currency) VALUES($1,$2,$3,'debit',$5,$6),($1,$2,$4,'credit',$5,$6)`,entry,org,accountID.String,clearing,in.Amount,currency)};if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO outbox_events(id,organization_id,aggregate_type,aggregate_id,event_type,payload) VALUES($1,$2,'refund',$3,'refund.completed',jsonb_build_object('refund_id',$3::text,'collection_id',$4::text,'amount',$5::bigint,'currency',$6::text))`,"evt_"+newID(),org,refundID,id,in.Amount,currency)};if err!=nil{writeJSON(w,500,problem{Error:"refund posting failed"});return};result:=map[string]any{"id":refundID,"collection_id":id,"status":"completed","amount":in.Amount,"currency":strings.TrimSpace(currency),"mode":"sandbox","notice":"simulated internal ledger refund; no external funds moved"};if err=storeIdempotency(r.Context(),tx,org,key,201,result);err!=nil{idempotencyFailure(w,r,err);return};if err=tx.Commit();err!=nil{writeJSON(w,409,problem{Error:"refund conflict"});return};writeJSON(w,201,result)
}
